100	func resolveSessionID(payload hookPayload) string {
101		if id := strings.TrimSpace(payload.SessionID); id != "" {
102			return id
103		}
104		if id := sessionIDFromFilename(hookSessionRef(payload)); id != "" {
105			return id
106		}
107		return readCachedSessionID()
108	}
109	
110	func hookSessionRef(payload hookPayload) string {
111		if ref := strings.TrimSpace(payload.SessionFile); ref != "" {
112			return ref
113		}
114		return strings.TrimSpace(payload.SessionRef)
115	}
