154	func cacheSessionID(id string) error {
155		if !validSessionID(id) {
156			return fmt.Errorf("unsafe session id %q", id)
157		}
158		if err := ensurePrivateDir(ompPrivateDir()); err != nil {
159			return err
160		}
161		return atomicWriteFile(cachedSessionPath(), []byte(id+"\n"), 0o600)
162	}
