202	func snapshotSession(source, cwd, sessionID string) (string, error) {
203		if !validSessionID(sessionID) {
204			return "", fmt.Errorf("unsafe session id %q", sessionID)
205		}
206		if strings.TrimSpace(source) == "" {
207			return "", errors.New("session file is required for agent_end")
208		}
209		if strings.TrimSpace(cwd) == "" {
210			return "", errors.New("cwd is required for agent_end snapshot")
211		}
212		sessionDir, err := New().GetSessionDir(cwd)
213		if err != nil {
214			return "", err
215		}
216		canonicalSessionDir, err := canonicalPath(sessionDir)
217		if err != nil {
218			return "", fmt.Errorf("resolve omp session directory: %w", err)
219		}
220		canonicalSource, err := canonicalPath(source)
221		if err != nil {
222			return "", fmt.Errorf("resolve omp session file: %w", err)
223		}
224		if filepath.Dir(canonicalSource) != canonicalSessionDir || filepath.Ext(canonicalSource) != ".jsonl" {
225			return "", errors.New("omp session file is outside the managed session directory")
226		}
227		info, err := os.Stat(canonicalSource)
228		if err != nil {
229			return "", fmt.Errorf("inspect omp session: %w", err)
230		}
231		if !info.Mode().IsRegular() {
232			return "", errors.New("omp session file is not a regular file")
233		}
234		src, err := os.Open(canonicalSource)
235		if err != nil {
236			return "", fmt.Errorf("open omp session: %w", err)
237		}
238		defer src.Close()
239	
240		snapshotDir := filepath.Join(canonicalSessionDir, ".entire")
241		if err := ensurePrivateDir(snapshotDir); err != nil {
242			return "", err
243		}
244		destination := filepath.Join(snapshotDir, sessionID+".jsonl")
245		tmp, err := os.CreateTemp(snapshotDir, ".snapshot-*")
246		if err != nil {
247			return "", fmt.Errorf("create transcript snapshot: %w", err)
248		}
249		tmpName := tmp.Name()
250		defer os.Remove(tmpName)
251	
252		if err := tmp.Chmod(0o600); err != nil {
253			return "", errors.Join(err, tmp.Close())
254		}
255		if _, err := io.Copy(tmp, src); err != nil {
256			return "", errors.Join(fmt.Errorf("copy transcript snapshot: %w", err), tmp.Close())
257		}
258		if err := tmp.Sync(); err != nil {
259			return "", errors.Join(fmt.Errorf("sync transcript snapshot: %w", err), tmp.Close())
260		}
261		if err := tmp.Close(); err != nil {
262			return "", fmt.Errorf("close transcript snapshot: %w", err)
263		}
264		if err := os.Rename(tmpName, destination); err != nil {
265			return "", fmt.Errorf("publish transcript snapshot: %w", err)
266		}
267		return destination, nil
268	}
