294	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
295		root := protocol.RepoRoot()
296		path := filepath.Join(root, extensionRelFile)
297		if data, err := os.ReadFile(path); err == nil {
298			if bytes.Equal(data, []byte(generatedExtension)) && !force {
299				return 0, nil
300			}
301			if !isOwnedExtension(data) && !force {
302				return 0, fmt.Errorf("refusing to overwrite foreign omp extension %s", path)
303			}
304		} else if !os.IsNotExist(err) {
305			return 0, err
306		}
307	
308		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
309			return 0, fmt.Errorf("create omp extension directory: %w", err)
310		}
311		if err := atomicWriteFile(path, []byte(generatedExtension), 0o600); err != nil {
312			return 0, fmt.Errorf("write omp extension: %w", err)
313		}
314		return 4, nil
315	}
316	
317	func (a *Agent) UninstallHooks() error {
318		root := protocol.RepoRoot()
319		path := filepath.Join(root, extensionRelFile)
320		data, err := os.ReadFile(path)
321		if os.IsNotExist(err) {
322			return nil
323		}
324		if err != nil {
325			return fmt.Errorf("read omp extension: %w", err)
326		}
327		if !isOwnedExtension(data) {
328			return nil
329		}
330		if err := os.Remove(path); err != nil {
331			return fmt.Errorf("remove omp extension: %w", err)
332		}
333		_ = os.Remove(filepath.Join(root, extensionRelDir))
334		return nil
335	}
