15	type compactLine struct {
16		V            int    `json:"v"`
17		Agent        string `json:"agent"`
18		CLIVersion   string `json:"cli_version"`
19		Type         string `json:"type"`
20		TS           string `json:"ts,omitempty"`
21		ID           string `json:"id,omitempty"`
22		InputTokens  int    `json:"input_tokens,omitempty"`
