49	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
50		data, err := os.ReadFile(sessionRef)
51		if err != nil {
52			return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
53		}
54		compacted, err := compactTranscriptBytes(data)
55		if err != nil {
56			return protocol.CompactTranscriptResponse{}, err
57		}
58		return protocol.CompactTranscriptResponse{Transcript: base64.StdEncoding.EncodeToString(compacted)}, nil
59	}
60	
61	func compactTranscriptBytes(data []byte) ([]byte, error) {
62		session, err := parseSession(data)
63		if err != nil {
64			return nil, err
65		}
66		results := collectOMPToolResults(session.Active)
67		var output bytes.Buffer
68		for _, record := range session.Active {
69			message := record.Entry.Message
70			if message == nil {
71				continue
72			}
73			switch message.Role {
74			case "user":
75				content := compactOMPUserBlocks(message.Content)
76				if len(content) == 0 {
77					continue
78				}
79				if err := writeCompactLine(&output, compactLine{
80					V: 1, Agent: "omp", CLIVersion: compactCLIVersion(), Type: "user",
81					TS: record.Entry.Timestamp, Content: content,
82				}); err != nil {
83					return nil, err
84				}
85			case "assistant":
86				content := compactAssistantBlocks(message.Content, results)
87				if len(content) == 0 {
88					continue
89				}
90				line := compactLine{
91					V: 1, Agent: "omp", CLIVersion: compactCLIVersion(), Type: "assistant",
92					TS: record.Entry.Timestamp, ID: record.Entry.ID, Content: content,
93				}
94				if message.Usage != nil {
95					line.InputTokens = message.Usage.Input
96					line.OutputTokens = message.Usage.Output
97				}
98				if err := writeCompactLine(&output, line); err != nil {
99					return nil, err
100				}
101			}
102		}
103		if output.Len() == 0 {
104			return nil, errors.New("compact transcript produced no output")
105		}
106		return output.Bytes(), nil
107	}
108	
109	func compactOMPUserBlocks(raw json.RawMessage) []compactUserBlock {
110		var text string
111		if json.Unmarshal(raw, &text) == nil {
112			if text == "" {
113				return nil
114			}
115			return []compactUserBlock{{Text: text}}
116		}
117		var output []compactUserBlock
118		for _, block := range messageBlocks(raw) {
119			if block.Type == "text" && block.Text != "" {
120				output = append(output, compactUserBlock{Text: block.Text})
121			}
122		}
123		return output
124	}
125	
126	func collectOMPToolResults(entries []parsedEntry) map[string]compactToolResult {
127		results := make(map[string]compactToolResult)
128		for _, record := range entries {
129			message := record.Entry.Message
130			if message == nil || message.Role != "toolResult" || message.ToolCallID == "" {
131				continue
132			}
133			status := "success"
134			if message.IsError {
135				status = "error"
136			}
137			results[message.ToolCallID] = compactToolResult{Output: messageText(message.Content), Status: status}
138		}
139		return results
140	}
141	
142	func compactAssistantBlocks(raw json.RawMessage, results map[string]compactToolResult) []any {
143		var output []any
144		for _, block := range messageBlocks(raw) {
145			switch block.Type {
146			case "text":
147				if block.Text != "" {
148					output = append(output, compactTextBlock{Type: "text", Text: block.Text})
149				}
150			case "toolCall":
151				if block.Name == "" {
152					continue
153				}
154				tool := compactToolBlock{
155					Type: "tool_use", ID: block.ID, Name: compactToolName(block.Name), Input: decodeToolArguments(block.Arguments),
156				}
157				if result, ok := results[block.ID]; ok {
158					tool.Result = &result
159				}
160				output = append(output, tool)
161			}
162		}
