357	func patchPaths(input string) []string {
358		lines := strings.Split(trimECMAScriptSpace(input), "\n")
359		if len(lines) >= 2 {
360			switch lines[0] {
361			case "<<EOF", "<<'EOF'", `<<"EOF"`:
362				if trimECMAScriptSpace(lines[len(lines)-1]) == "EOF" {
363					lines = lines[1 : len(lines)-1]
364				}
365			}
366		}
367		if len(lines) < 3 ||
368			trimECMAScriptSpace(lines[0]) != "*** Begin Patch" ||
369			trimECMAScriptSpace(lines[len(lines)-1]) != "*** End Patch" {
370			return nil
371		}
372	
373		var paths []string
374		for remaining := lines[1 : len(lines)-1]; len(remaining) > 0; {
375			if trimECMAScriptSpace(remaining[0]) == "" {
376				remaining = remaining[1:]
377				continue
378			}
379	
380			firstLine := trimECMAScriptSpace(remaining[0])
381			switch {
382			case strings.HasPrefix(firstLine, "*** Add File: "):
383				paths = append(paths, firstLine[len("*** Add File: "):])
384				consumed := 1
385				for consumed < len(remaining) && strings.HasPrefix(remaining[consumed], "+") {
386					consumed++
387				}
388				remaining = remaining[consumed:]
389			case strings.HasPrefix(firstLine, "*** Delete File: "):
390				paths = append(paths, firstLine[len("*** Delete File: "):])
391				remaining = remaining[1:]
392			case strings.HasPrefix(firstLine, "*** Update File: "):
393				paths = append(paths, firstLine[len("*** Update File: "):])
394				remaining = remaining[1:]
395	
396				if len(remaining) > 0 && strings.HasPrefix(remaining[0], "*** Move to: ") {
397					paths = append(paths, remaining[0][len("*** Move to: "):])
398					remaining = remaining[1:]
399				}
400	
401				diffLines := 0
402				for len(remaining) > 0 &&
403					!strings.HasPrefix(remaining[0], "*** Add File:") &&
404					!strings.HasPrefix(remaining[0], "*** Delete File:") &&
405					!strings.HasPrefix(remaining[0], "*** Update File:") {
406					diffLines++
407					remaining = remaining[1:]
408				}
409				if diffLines == 0 {
410					return nil
411				}
412			default:
413				return nil
414			}
415		}
416		return paths
417	}
418	
419	func trimECMAScriptSpace(s string) string {
420		return strings.TrimFunc(s, func(r rune) bool {
421			return unicode.Is(unicode.Zs, r) ||
422				r == '\uFEFF' ||
423				r == '\t' || r == '\v' || r == '\f' ||
424				r == '\n' || r == '\r' || r == '\u2028' || r == '\u2029'
425		})
426	}
427	
428	func isWriteTool(name string) bool {
429		switch normalizeToolName(name) {
430		case "write", "edit", "apply_patch":
431			return true
432		default:
433			return false
434		}
435	}
436	
437	func normalizeToolName(name string) string {
438		name = strings.ToLower(strings.TrimSpace(name))
439		name = strings.ReplaceAll(name, "-", "_")
440		if index := strings.LastIndexAny(name, ".:/"); index >= 0 {
441			name = name[index+1:]
442		}
443		return name
444	}
445	
446	func messageText(raw json.RawMessage) string {
447		var text string
448		if json.Unmarshal(raw, &text) == nil {
449			return text
450		}
451		var parts []string
452		for _, block := range messageBlocks(raw) {
453			if block.Type == "text" && block.Text != "" {
454				parts = append(parts, block.Text)
455			}
456		}
457		return strings.Join(parts, "\n")
458	}
459	
460	func messageBlocks(raw json.RawMessage) []contentBlock {
461		var encoded []json.RawMessage
462		if json.Unmarshal(raw, &encoded) != nil {
463			return nil
464		}
465		blocks := make([]contentBlock, 0, len(encoded))
466		for _, item := range encoded {
467			var block contentBlock
468			if json.Unmarshal(item, &block) == nil && block.Type != "" {
469				blocks = append(blocks, block)
470			}
471		}
472		return blocks
473	}
