	ompBusyPattern       = `(?m)^[\t ]*(?:[⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏] [^\r\n]*(?:⟦esc⟧|⟨esc⟩)|[-\\|/] [^\r\n]*\[esc\])[\t ]*$`
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "omp" {
		return
	}
	Register(&OMP{})
	RegisterGate("omp", 1)
}

type OMP struct{}

type ompSession struct {
	*TmuxSession
}

func (s *ompSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	return s.TmuxSession.WaitFor(pattern, time.Duration(float64(timeout)*ompTimeoutMultiplier))
}

func (o *OMP) Name() string               { return "omp" }
func (o *OMP) Binary() string             { return "omp" }
func (o *OMP) EntireAgent() string        { return "omp" }
func (o *OMP) PromptPattern() string      { return `╭──` }
func (o *OMP) TimeoutMultiplier() float64 { return ompTimeoutMultiplier }
func (o *OMP) IsExternalAgent() bool      { return true }

func (o *OMP) IsTransientError(out Output, _ error) bool {
	combined := strings.ToLower(out.Stdout + out.Stderr)
	patterns := []string{
		"overloaded",
		"rate limit",
		"429",
		"503",
		"econnreset",
		"etimedout",
		"timeout",
	}
	for _, pattern := range patterns {
		if strings.Contains(combined, pattern) {
			return true
		}
	}
	return false

	enc.SetIndent("", "  ")
	if err := enc.Encode(map[string]any{"hooks": rules}); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
	if !force && a.AreHooksInstalled() {
		return 0, nil
	}
	repoRoot := protocol.RepoRoot()
	hooksPath := filepath.Join(repoRoot, hooksRelFile)
	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
		return 0, err
	}
	content, err := hooksFileContent()
	if err != nil {
		return 0, err
	}
	if err := os.WriteFile(hooksPath, content, 0o600); err != nil {
		return 0, err
	}
	return len(nativeHookEvents), nil
}

func (a *Agent) UninstallHooks() error {
	repoRoot := protocol.RepoRoot()
	hooksPath := filepath.Join(repoRoot, hooksRelFile)
	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
		return err
	}
	// Remove the now-empty plugin directories; leave them if the user added
	// other files to the plugin.
	_ = os.Remove(filepath.Dir(hooksPath))
	_ = os.Remove(filepath.Join(repoRoot, pluginRelDir))
	return nil
}

func (a *Agent) AreHooksInstalled() bool {
	data, err := os.ReadFile(filepath.Join(protocol.RepoRoot(), hooksRelFile))
	if err != nil {
		return false
	}
	var file struct {
		Hooks map[string][]struct {
			Hooks []struct {
				Command string `json:"command"`
			} `json:"hooks"`
		} `json:"hooks"`
	}
	if err := json.Unmarshal(data, &file); err != nil {
		return false
	}
	for _, h := range nativeHookEvents {
		found := false
		for _, rule := range file.Hooks[h.Event] {
			for _, action := range rule.Hooks {
				if action.Command == hookCommand+h.Verb {
					found = true
				}
			}
		}
		if !found {
			return false
		}
	}
	return true
}

