13	// CommandRunner runs `kilo` CLI commands for transcript refresh. The default
14	// implementation shells out to the binary. Tests substitute their own runner.
15	type CommandRunner interface {
16		// ExportSession fetches the Kilo session JSON for sessionID and writes it
17		// to outputPath. Returns the output path on success.
18		ExportSession(ctx context.Context, sessionID string, outputPath string) (string, error)
19	}
20	
21	type DefaultCommandRunner struct{}
22	
23	func (r *DefaultCommandRunner) ExportSession(ctx context.Context, sessionID string, outputPath string) (string, error) {
24		if strings.TrimSpace(sessionID) == "" {
25			return "", errors.New("session id is required")
26		}
27		if strings.TrimSpace(outputPath) == "" {
28			return "", errors.New("output path is required")
29		}
30		if err := os.MkdirAll(filepath.Dir(outputPath), 0o750); err != nil {
31			return "", fmt.Errorf("create output dir: %w", err)
32		}
33	
34		cmd := exec.CommandContext(ctx, "kilo", "session", "show", "--format", "json", sessionID)
35		cmd.Env = kiloEnv()
36		out, err := cmd.Output()
37		if err != nil {
38			var exitErr *exec.ExitError
39			if errors.As(err, &exitErr) {
40				return "", fmt.Errorf("kilo session show %s: %w: %s", sessionID, err, strings.TrimSpace(string(exitErr.Stderr)))
41			}
42			return "", fmt.Errorf("kilo session show %s: %w", sessionID, err)
43		}
44		if err := os.WriteFile(outputPath, out, 0o600); err != nil {
45			return "", fmt.Errorf("write exported session: %w", err)
46		}
47	
48		return outputPath, nil
49	}
50	
51	// kiloEnv returns the parent environment without Bun bootstrap variables.
52	//
53	// The `kilo` CLI is a Bun-compiled native binary distributed alongside Kilo's
54	// plugin runtime. When invoked from inside a Kilo plugin (which itself runs
55	// on Bun), variables like `BUN_BE_BUN` leak into the child process and make
56	// the compiled binary re-interpret its argv as a Bun script invocation.
57	// Removing the Bun bootstrap variables forces `kilo` to execute its compiled
58	// entrypoint instead.
59	func kiloEnv() []string {
60		parent := os.Environ()
61		out := make([]string, 0, len(parent))
62		for _, kv := range parent {
63			key, _, _ := strings.Cut(kv, "=")
64			if isBunEnvVar(key) {
65				continue
66			}
67			out = append(out, kv)
68		}
69		return out
70	}
71	
72	func isBunEnvVar(key string) bool {
73		switch key {
74		case "BUN_BE_BUN", "BUN_INTERNAL_IPC_FD", "BUN_INSPECT", "BUN_INSPECT_NOTIFY", "BUN_INSPECT_CONNECT_TO":
75			return true
76		}
77		return strings.HasPrefix(key, "BUN_DEBUG_")
78	}
