166	// writeSessionPayload merges the optional session metadata and messages array
167	// from a hook payload into a single Session JSON document at sessionRef.
168	func writeSessionPayload(sessionRef, sessionID string, sessionRaw, messagesRaw json.RawMessage) error {
169		if strings.TrimSpace(sessionRef) == "" {
170			return errors.New("session_ref is required")
171		}
172		if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
173			return err
174		}
175	
176		var session Session
177		if len(sessionRaw) > 0 {
178			if err := json.Unmarshal(sessionRaw, &session); err != nil {
179				return fmt.Errorf("parse session payload: %w", err)
180			}
181		}
182		if session.ID == "" {
183			session.ID = sessionID
184		}
185		if len(messagesRaw) > 0 {
186			var messages []SessionMessage
187			if err := json.Unmarshal(messagesRaw, &messages); err != nil {
188				return fmt.Errorf("parse messages payload: %w", err)
189			}
