353	    try {
354	      const [session, messages] = await Promise.all([
355	        client.session.get({ path: { id: sessionID } }),
356	        client.session.messages({ path: { id: sessionID } }),
357	      ])
358	      return { session: session.data, messages: messages.data }
359	    } catch {
360	      return null
361	    }
362	  }
363	
364	  return {
365	    event: async ({ event }) => {
366	      try {
367	        switch (event.type) {
368	          case "session.created": {
369	            const session = (event as any).properties?.info
370	            if (!session?.id) break
371	            // Sub-sessions are tracked by Kilo too; only top-level ones get an
372	            // Entire SessionStart.
373	            if (session.parentID) break
374	            if (announcedSessions.has(session.id)) break
375	            announcedSessions.add(session.id)
376	            if (resetSessionTracking(session.id)) {
377	              callHookSync("session-start", { session_id: session.id })
378	            }
379	            break
380	          }
381	
382	          case "message.updated": {
383	            const msg = (event as any).properties?.info
384	            if (!msg) break
385	            if (msg.sessionID && resetSessionTracking(msg.sessionID) && !announcedSessions.has(msg.sessionID)) {
386	              announcedSessions.add(msg.sessionID)
387	              callHookSync("session-start", { session_id: msg.sessionID })
388	            }
389	            messageStore.set(msg.id, msg)
390	            if (msg.role === "assistant" && msg.modelID) {
391	              currentModel = msg.modelID
392	            }
393	            if (msg.role === "user" && !seenUserMessages.has(msg.id)) {
394	              seenUserMessages.add(msg.id)
395	              const sessionID = msg.sessionID ?? currentSessionID
396	              if (sessionID) {
397	                callHookSync("turn-start", {
398	                  session_id: sessionID,
399	                  prompt: "",
400	                  model: currentModel ?? "",
401	                })
402	              }
403	            }
404	            break
405	          }
406	
407	          case "message.part.updated": {
408	            const part = (event as any).properties?.part
409	            if (!part?.messageID) break
410	            const msg = messageStore.get(part.messageID)
411	            if (msg?.role === "user" && part.type === "text" && !seenUserMessages.has(msg.id)) {
412	              seenUserMessages.add(msg.id)
413	              const sessionID = msg.sessionID ?? currentSessionID
414	              if (sessionID) {
415	                callHookSync("turn-start", {
416	                  session_id: sessionID,
417	                  prompt: part.text ?? "",
418	                  model: currentModel ?? "",
419	                })
420	              }
421	            }
422	            break
423	          }
424	
425	          case "session.status": {
426	            // session.status fires reliably in both TUI and ` + "`kilo run`" + ` mode.
427	            // session.idle is deprecated upstream and not always emitted on run exit.
428	            const props = (event as any).properties
429	            if (props?.status?.type !== "idle") break
430	            const sessionID = props?.sessionID ?? currentSessionID
431	            if (!sessionID) break
432	            const snapshot = await snapshotSession(sessionID)
433	            callHookSync("turn-end", {
434	              session_id: sessionID,
435	              model: currentModel ?? "",
436	              session: snapshot?.session ?? null,
437	              messages: snapshot?.messages ?? [],
438	            })
439	            break
440	          }
441	
442	          case "session.compacted": {
443	            const sessionID = (event as any).properties?.sessionID
444	            if (!sessionID) break
445	            await callHook("compaction", { session_id: sessionID })
446	            break
447	          }
448	
449	          case "session.deleted": {
450	            const session = (event as any).properties?.info
451	            if (!session?.id) break
452	            seenUserMessages.clear()
453	            messageStore.clear()
454	            announcedSessions.delete(session.id)
455	            currentSessionID = null
456	            callHookSync("session-end", { session_id: session.id })
457	            break
458	          }
459	
460	          case "server.instance.disposed": {
461	            // Fires on Kilo shutdown (TUI close or ` + "`kilo run`" + ` exit).
462	            // session.deleted only fires on explicit user deletion, so this is
463	            // the only reliable terminator on process exit.
464	            if (!currentSessionID) break
465	            const sessionID = currentSessionID
466	            seenUserMessages.clear()
467	            messageStore.clear()
468	            announcedSessions.delete(sessionID)
469	            currentSessionID = null
470	            callHookSync("session-end", { session_id: sessionID })
471	            break
472	          }
473	        }
474	      } catch {
475	        // Silently ignore — plugin failures must not crash Kilo.
476	      }
477	    },
478	  }
479	}
480	
481	export default { id: "entire-agent-kilo", server: EntirePlugin }
482	`
483	}
484	
485	func transcriptPath(sessionID string) string {
486		return filepath.Join(protocol.DefaultSessionDir(protocol.RepoRoot()), transcriptSubdir, safeSessionID(sessionID)+".json")
487	}
488	
489	func safeSessionID(sessionID string) string {
490		if sessionID == "" {
491			return "unknown"
492		}
493		re := regexp.MustCompile(`[^A-Za-z0-9_.-]+`)
494		return re.ReplaceAllString(sessionID, "_")
495	}
