1	package kilo
2	
3	import (
4		"bytes"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"strings"
11	
12		"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
13	)
14	
15	const (
16		compactTranscriptAgent      = "kilo"
17		compactTranscriptCLIVersion = "unknown"
18	)
19	
20	type compactTranscriptLine struct {
21		V            int    `json:"v"`
22		Agent        string `json:"agent"`
23		CLIVersion   string `json:"cli_version"`
24		Type         string `json:"type"`
25		TS           string `json:"ts,omitempty"`
26		ID           string `json:"id,omitempty"`
27		InputTokens  int    `json:"input_tokens,omitempty"`
28		OutputTokens int    `json:"output_tokens,omitempty"`
29		Content      any    `json:"content"`
30	}
31	
32	type compactUserTextBlock struct {
33		Text string `json:"text"`
34	}
35	
36	type compactAssistantTextBlock struct {
37		Type string `json:"type"`
38		Text string `json:"text"`
39	}
40	
41	type compactAssistantToolUseBlock struct {
42		Type   string                 `json:"type"`
43		ID     string                 `json:"id,omitempty"`
44		Name   string                 `json:"name"`
45		Input  any                    `json:"input"`
46		Result *compactToolResultJSON `json:"result,omitempty"`
47	}
48	
49	type compactToolResultJSON struct {
50		Output string `json:"output"`
51		Status string `json:"status"`
52	}
53	
54	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
55		data, err := os.ReadFile(sessionRef)
56		if err != nil {
57			return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
58		}
59		compacted, err := compactTranscriptBytes(data)
60		if err != nil {
61			return protocol.CompactTranscriptResponse{}, err
62		}
63		return protocol.CompactTranscriptResponse{Transcript: base64.StdEncoding.EncodeToString(compacted)}, nil
64	}
65	
66	func compactTranscriptBytes(data []byte) ([]byte, error) {
67		session, err := parseKiloSession(data)
68		if err != nil {
69			return nil, err
70		}
71		if len(session.Messages) == 0 {
72			return nil, errors.New("compact transcript produced no output")
73		}
74	
75		cliVersion := compactCLIVersion()
76		var buf bytes.Buffer
77		for _, msg := range session.Messages {
78			switch msg.Info.Role {
79			case MessageRoleUser:
80				content := compactUserContent(msg.Parts)
81				if len(content) == 0 {
82					continue
83				}
84				if err := writeCompactTranscriptLine(&buf, compactTranscriptLine{
85					V:          1,
86					Agent:      compactTranscriptAgent,
87					CLIVersion: cliVersion,
88					Type:       "user",
89					TS:         messageTimestamp(msg),
90					Content:    content,
91				}); err != nil {
92					return nil, err
93				}
94			case MessageRoleAssistant:
95				content := compactAssistantContent(msg.Parts)
96				if len(content) == 0 {
97					continue
98				}
99				line := compactTranscriptLine{
100					V:          1,
101					Agent:      compactTranscriptAgent,
102					CLIVersion: cliVersion,
103					Type:       "assistant",
104					TS:         messageTimestamp(msg),
105					ID:         msg.Info.ID,
106					Content:    content,
107				}
108				if msg.Info.Tokens != nil {
109					line.InputTokens = msg.Info.Tokens.Input
110					line.OutputTokens = msg.Info.Tokens.Output
111				}
112				if err := writeCompactTranscriptLine(&buf, line); err != nil {
113					return nil, err
114				}
115			}
116		}
117		if buf.Len() == 0 {
118			return nil, errors.New("compact transcript produced no output")
119		}
120		return buf.Bytes(), nil
121	}
122	
123	func compactUserContent(parts []MessagePart) []compactUserTextBlock {
124		out := make([]compactUserTextBlock, 0, len(parts))
125		for _, part := range parts {
126			if part.Type == PartText && part.Text != "" {
127				out = append(out, compactUserTextBlock{Text: part.Text})
128			}
129		}
130		return out
131	}
132	
133	func compactAssistantContent(parts []MessagePart) []any {
134		out := make([]any, 0, len(parts))
135		for _, part := range parts {
136			switch part.Type {
137			case PartText:
138				if part.Text != "" {
139					out = append(out, compactAssistantTextBlock{Type: "text", Text: part.Text})
140				}
141			case PartTool:
142				tool := compactAssistantToolUseBlock{
143					Type:  "tool_use",
144					ID:    part.CallID,
145					Name:  part.Tool,
146					Input: decodeRawInput(part.State),
147				}
148				if result := toolResultFromState(part.State); result != nil {
149					tool.Result = result
150				}
151				out = append(out, tool)
152			}
153		}
154		return out
155	}
156	
157	func decodeRawInput(state *ToolState) any {
158		if state == nil || len(state.Input) == 0 {
159			return map[string]any{}
160		}
161		var decoded any
162		if err := json.Unmarshal(state.Input, &decoded); err != nil {
163			return string(state.Input)
164		}
165		return decoded
166	}
167	
168	func toolResultFromState(state *ToolState) *compactToolResultJSON {
169		if state == nil {
170			return nil
171		}
172		if state.Output == "" && state.Error == "" {
173			return nil
174		}
175		status := "success"
176		output := state.Output
177		if state.Error != "" || strings.EqualFold(state.Status, "error") {
178			status = "error"
179			if output == "" {
180				output = state.Error
181			}
182		}
183		return &compactToolResultJSON{Output: output, Status: status}
184	}
185	
186	func writeCompactTranscriptLine(buf *bytes.Buffer, line compactTranscriptLine) error {
187		encoded, err := json.Marshal(line)
188		if err != nil {
189			return err
190		}
191		buf.Write(encoded)
192		return buf.WriteByte('\n')
193	}
194	
195	func compactCLIVersion() string {
196		if version := strings.TrimSpace(os.Getenv("ENTIRE_CLI_VERSION")); version != "" {
197			return version
198		}
199		return compactTranscriptCLIVersion
200	}
