14	
15		"github.com/entireio/external-agents/agents/entire-agent-kilo/internal/protocol"
16	)
17	
18	const prepareTranscriptTimeout = 30 * time.Second
19	
20	func parseKiloSession(data []byte) (*Session, error) {
21		trimmed := bytes.TrimSpace(data)
22		if len(trimmed) == 0 {
23			return &Session{}, nil
24		}
25		if trimmed[0] != '{' {
26			return nil, errors.New("kilo session is not prepared: run prepare-transcript first")
27		}
28		var session Session
29		if err := json.Unmarshal(trimmed, &session); err != nil {
30			return nil, fmt.Errorf("parse kilo session: %w", err)
31		}
32		return &session, nil
33	}
34	
35	// sessionIDFromTranscriptData extracts the session id from a transcript blob.
36	// Returns ("", nil) when the blob is empty or parses to a Session with no id —
37	// callers treat that as a graceful no-op (nothing to refresh from).
38	func sessionIDFromTranscriptData(data []byte) (string, error) {
39		trimmed := bytes.TrimSpace(data)
40		if len(trimmed) == 0 {
41			return "", nil
42		}
43		session, err := parseKiloSession(trimmed)
44		if err != nil {
45			return "", err
46		}
47		return session.ID, nil
48	}
49	
50	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
51		var sessionID string
52		var sessionRef string
53		if input != nil {
54			sessionID = input.SessionID
55			sessionRef = input.SessionRef
56			if sessionRef == "" && sessionID != "" {
57				sessionRef = transcriptPath(sessionID)
58			}
59		}
60		if sessionRef == "" {
61			return protocol.AgentSessionJSON{}, errors.New("session_ref or session_id is required")
62		}
63	
64		data, err := os.ReadFile(sessionRef)
65		if err != nil {
66			return protocol.AgentSessionJSON{}, err
67		}
68		session, err := parseKiloSession(data)
69		if err != nil {
70			return protocol.AgentSessionJSON{}, err
71		}
72		if session.ID == "" {
73			if sessionID == "" {
74				sessionID = strings.TrimSuffix(filepath.Base(sessionRef), filepath.Ext(sessionRef))
75			}
76			return protocol.AgentSessionJSON{
77				SessionID:     sessionID,
78				AgentName:     "kilo",
79				RepoPath:      protocol.RepoRoot(),
80				SessionRef:    sessionRef,
81				StartTime:     time.Now().UTC().Format(time.RFC3339),
82				NativeData:    data,
83				ModifiedFiles: []string{},
84				NewFiles:      []string{},
85				DeletedFiles:  []string{},
86			}, nil
87		}
88	
89		startTime := sessionStartTime(session)
90	
91		return protocol.AgentSessionJSON{
92			SessionID:     session.ID,
93			AgentName:     "kilo",
94			RepoPath:      protocol.RepoRoot(),
95			SessionRef:    sessionRef,
96			StartTime:     startTime.Format(time.RFC3339),
97			NativeData:    data,
98			ModifiedFiles: modifiedFilesFromSession(session),
99			NewFiles:      []string{},
100			DeletedFiles:  []string{},
101		}, nil
102	}
103	
104	func sessionStartTime(session *Session) time.Time {
105		if session != nil && session.Time != nil {
106			if t := session.Time.Created.Time(); !t.IsZero() {
107				return t
108			}
109			if t := session.Time.Updated.Time(); !t.IsZero() {
110				return t
111			}
112		}
113		return time.Now().UTC()
114	}
115	
116	func (a *Agent) PrepareTranscript(sessionRef string) error {
117		if strings.TrimSpace(sessionRef) == "" {
118			return errors.New("session_ref is required")
119		}
120		data, err := os.ReadFile(sessionRef)
121		if err != nil {
122			return fmt.Errorf("read transcript for prepare: %w", err)
123		}
124		sessionID, err := sessionIDFromTranscriptData(data)
125		if err != nil {
126			return err
127		}
128		if sessionID == "" {
129			return nil
130		}
131		return a.fetchSession(sessionID, sessionRef)
132	}
133	
134	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
135		if session.SessionRef == "" {
136			return errors.New("session_ref is required")
137		}
138		if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
139			return err
140		}
141		return os.WriteFile(session.SessionRef, session.NativeData, 0o600)
142	}
143	
144	func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
145		data, err := os.ReadFile(sessionRef)
146		if err != nil {
147			return nil, err
148		}
149		if _, err := parseKiloSession(data); err != nil {
150			return nil, err
151		}
152		return data, nil
153	}
