155	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
156		if maxSize <= 0 {
157			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
158		}
159		var chunks [][]byte
160		for len(content) > 0 {
161			end := min(maxSize, len(content))
162			chunks = append(chunks, content[:end])
163			content = content[end:]
164		}
165		return chunks, nil
166	}
167	
168	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
169		var data []byte
170		for _, chunk := range chunks {
171			data = append(data, chunk...)
172		}
173		return data, nil
174	}
