176	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
177		data, err := os.ReadFile(path)
178		if err != nil {
179			if os.IsNotExist(err) {
180				return 0, nil
181			}
182			return 0, err
183		}
184		session, err := parseKiloSession(data)
185		if err != nil {
186			return 0, err
187		}
188		return len(session.Messages), nil
189	}
