191	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
192		data, err := os.ReadFile(path)
193		if err != nil {
194			return nil, 0, err
195		}
196		session, err := parseKiloSession(data)
197		if err != nil {
198			return nil, 0, err
199		}
200		return modifiedFilesFromSessionOffset(session, offset), len(session.Messages), nil
201	}
