203	func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
204		data, err := os.ReadFile(sessionRef)
205		if err != nil {
206			return nil, err
207		}
208		session, err := parseKiloSession(data)
209		if err != nil {
210			return nil, err
211		}
212		var prompts []string
213		for _, msg := range sessionMessagesFromOffset(session, offset) {
214			if msg.Info.Role != MessageRoleUser {
215				continue
216			}
217			if text := messageText(msg); text != "" {
218				prompts = append(prompts, text)
219			}
