224	func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
225		data, err := os.ReadFile(sessionRef)
226		if err != nil {
227			return "", false, err
228		}
229		session, err := parseKiloSession(data)
230		if err != nil {
231			return "", false, err
232		}
233		for i := len(session.Messages) - 1; i >= 0; i-- {
234			msg := session.Messages[i]
235			if msg.Info.Role != MessageRoleAssistant {
236				continue
237			}
238			if text := messageText(msg); text != "" {
239				return text, true, nil
240			}
241		}
242		return "", false, nil
243	}
244	
245	func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
246		session, err := parseKiloSession(data)
247		if err != nil {
248			return protocol.TokenUsageResponse{}, err
249		}
250		var usage protocol.TokenUsageResponse
251		for _, msg := range sessionMessagesFromOffset(session, offset) {
252			if msg.Info.Role != MessageRoleAssistant || msg.Info.Tokens == nil {
253				continue
254			}
255			tokens := msg.Info.Tokens
256			usage.InputTokens += tokens.Input
257			usage.OutputTokens += tokens.Output
258			if tokens.Cache != nil {
259				usage.CacheReadTokens += tokens.Cache.Read
260				usage.CacheCreationTokens += tokens.Cache.Write
261			}
262			usage.APICallCount++
263		}
264		return usage, nil
265	}
