267	func sessionMessagesFromOffset(session *Session, offset int) []SessionMessage {
268		if session == nil || len(session.Messages) == 0 {
269			return nil
270		}
271		if offset < 0 {
272			offset = 0
273		}
274		if offset >= len(session.Messages) {
275			return nil
276		}
277		return session.Messages[offset:]
278	}
