280	func latestSessionModel(session *Session) string {
281		if session == nil {
282			return ""
283		}
284		for i := len(session.Messages) - 1; i >= 0; i-- {
285			info := session.Messages[i].Info
286			if info.Role != MessageRoleAssistant {
287				continue
288			}
289			if model := strings.TrimSpace(info.ModelID); model != "" {
290				return model
291			}
292		}
293		return ""
294	}
