308	}
309	
310	func modifiedFilesFromMessages(messages []SessionMessage) []string {
311		seen := map[string]bool{}
312		for _, msg := range messages {
313			for _, file := range modifiedFilesFromMessage(msg) {
314				if file != "" {
315					seen[file] = true
316				}
317			}
318		}
319		files := make([]string, 0, len(seen))
320		for file := range seen {
321			files = append(files, file)
322		}
323		sort.Strings(files)
324		return files
325	}
326	
327	// toolInputFileKeys lists the JSON object keys to scan on a tool call's
328	// `state.input` for file paths. Includes single-path and multi-path forms.
329	var toolInputFileKeys = []string{"path", "filePath", "filepath", "file", "absolutePath", "paths", "files"}
330	
331	// toolMetadataFileKeys lists the JSON object keys to scan on a tool call's
332	// `state.metadata` (Kilo wraps the resolved path here for write/edit tools).
333	var toolMetadataFileKeys = []string{"filePath", "filepath", "path", "absolutePath"}
334	
335	func modifiedFilesFromMessage(msg SessionMessage) []string {
336		var files []string
337		for _, part := range msg.Parts {
338			if part.Type != PartTool || part.State == nil || !isMutatingToolName(part.Tool) {
339				continue
340			}
341			files = append(files, filePathsFromJSON(part.State.Input, toolInputFileKeys)...)
342			files = append(files, filePathsFromJSON(part.State.Metadata, toolMetadataFileKeys)...)
343		}
344		return cleanFiles(files)
345	}
346	
347	func filePathsFromJSON(raw json.RawMessage, keys []string) []string {
348		if len(raw) == 0 {
349			return nil
350		}
351		var obj map[string]json.RawMessage
352		if err := json.Unmarshal(raw, &obj); err != nil {
353			return nil
354		}
355		var files []string
356		for _, key := range keys {
357			files = append(files, stringValues(obj[key])...)
358		}
359		return files
360	}
