	// Kilo session blob, not a message line.
	if !more && len(probe.Messages) > 0 && len(probe.Info) == 0 {
		var session Session
		if err := json.Unmarshal(first, &session); err != nil {
			return nil, fmt.Errorf("parse kilo session blob: %w", err)
		}
		return session.Messages, nil
	}

